import{createHash}from"node:crypto";export function buildGovernanceEvidenceBundleEntry({evidenceClass,artifactHash,provenanceHash,freshnessHash}){if(!evidenceClass||![artifactHash,provenanceHash,freshnessHash].every(x=>/^[a-f0-9]{64}$/.test(x||"")))throw Error("entry invalid");let b={kind:"governance-evidence-bundle-entry/v1",evidenceClass,artifactHash,provenanceHash,freshnessHash};return Object.freeze({...b,entryHash:createHash("sha256").update(JSON.stringify(b)).digest("hex")})}
